class PoolError(Exception): pass

class Pool:
    def __init__(self, maxconn):
        self.free = [f"c{i}" for i in range(maxconn)]
    def getconn(self):
        if not self.free:
            raise PoolError("connection pool exhausted")
        return self.free.pop(0)
    def putconn(self, c):
        self.free.append(c)
pool = Pool(2)
for i in range(4):
    try:
        conn = pool.getconn()
        if i % 2 == 0:
            raise ValueError("bad row")
        pool.putconn(conn)
        print(i, "ok", conn)
    except ValueError:
        print(i, "failed, leaked", conn)
    except PoolError as e:
        print(i, e)
